const out = [];
let idx = 0;
for (const item of $('Compression').all()) {
  const binary = item.binary || {};
  for (const key of Object.keys(binary)) {
    idx++;
    out.push({
      json: { fileName: binary[key].fileName, sheetNumber: String(idx) },
      binary: { data: binary[key] },
    });
  }
}
return out;

const items = $input.all();
const sheetNumber = $('Loop Over Files Rekap').first().json.sheetNumber;
const COLS = 25;

const values = [];
for (const item of items) {
  const row = item.json.row || [];
  const r = [];
  for (let i = 0; i < COLS; i++) {
    r.push(row[i] === null || row[i] === undefined ? '' : row[i]);
  }
  values.push(r);
}

// GIN ada di W8 (W8:X8 di-merge), baris ke-8 = index 7, kolom W = index 22
const gin = String(values[7]?.[22] ?? '').trim();

const processedRows = $('Read Processed Attachments').first().json.values || [];
const processedGINs = new Set(
  processedRows.map(row => String(row[3] ?? '').trim()).filter(g => g !== '')
);

// kalau GIN gagal kebaca, anggap baru (aman, lanjut proses normal) daripada diam-diam skip
const isNewGin = gin === '' || !processedGINs.has(gin);

// tab 'Rekap Calc' di file Copy Transaksi harus keisi berurutan dari tab 1 tanpa celah
// (formula Summary-nya cuma jalan kalau data mulai dari tab 1), jadi file yang baru
// dinomori ulang berurutan, bukan pakai posisi aslinya di dalam email.
// Pakai scope 'global' supaya node lain (guard/notifikasi/logging setelah loop) bisa baca juga.
const staticData = $getWorkflowStaticData('global');
if (sheetNumber === '1') {
  staticData.newFileTabCounter = 0; // reset tiap awal eksekusi baru
  staticData.duplicateFiles = [];
  staticData.newGins = [];
}

let sheetName = sheetNumber;
if (isNewGin) {
  staticData.newFileTabCounter = (staticData.newFileTabCounter || 0) + 1;
  sheetName = String(staticData.newFileTabCounter);
  if (gin !== '') staticData.newGins.push(gin);
} else {
  const fileName = $('Loop Over Files Rekap').first().json.fileName;
  if (!staticData.duplicateFiles) staticData.duplicateFiles = [];
  staticData.duplicateFiles.push({ fileName, gin });
}

return [{ json: { sheetName, values, gin, isNewGin } }];

const data = $input.first().json; // { sheetName, values }
const fileName = $('Loop Over Files Rekap').first().json.fileName;

function isEmpty(v) {
  return v === null || v === undefined || v === '';
}
function countFilled(row) {
  return row.filter(v => !isEmpty(v)).length;
}

const values = data.values;
const HEADER_ROWS = 15; // baris info laporan (nama perusahaan, tanggal, dll), dilewati dari cek
const anomalies = [];

for (let i = HEADER_ROWS; i < values.length; i++) {
  const row = values[i];
  const filled = countFilled(row);
  if (filled === 0) continue; // baris kosong total itu wajar (misal akhir data)

  const prev = values[i - 1] ? countFilled(values[i - 1]) : 0;
  const next = values[i + 1] ? countFilled(values[i + 1]) : 0;
  const neighborAvg = (prev + next) / 2;

  // baris ini jauh lebih "kosong" dibanding tetangga kiri-kanannya -> mencurigakan
  if (filled <= 2 && neighborAvg >= 5) {
    anomalies.push({ rowIndex: i, filled, neighborAvg, row });
  }
}

return [{
  json: {
    ...data,
    fileName,
    hasAnomaly: anomalies.length > 0,
    anomalies,
  }
}];

const json = $('Validate Extraction').first().json;
if (json.hasAnomaly) {
  const staticData = $getWorkflowStaticData('node');
  if (!staticData.anomalyFiles) staticData.anomalyFiles = [];
  staticData.anomalyFiles.push({
    fileName: json.fileName,
    sheetName: json.sheetName,
    anomalyCount: json.anomalies.length,
    sampleRows: json.anomalies.slice(0, 3).map(a => a.rowIndex),
  });
}
return $input.all();

const staticData = $getWorkflowStaticData('node');
const anomalyFiles = staticData.anomalyFiles || [];

let summaryText = 'Rekap Harian selesai diproses.\n';
if (anomalyFiles.length > 0) {
  summaryText += '\n⚠️ Ditemukan kemungkinan masalah format (merge cell/kolom hilang) di ' + anomalyFiles.length + ' file:\n';
  for (const f of anomalyFiles) {
    summaryText += '- ' + f.fileName + ' (sheet ' + f.sheetName + '): ' + f.anomalyCount + ' baris mencurigakan, contoh baris ke-' + f.sampleRows.join(', ') + '\n';
  }
  summaryText += '\nMohon cek manual file-file di atas.';
} else {
  summaryText += 'Tidak ada anomali format terdeteksi.';
}

staticData.anomalyFiles = []; // reset untuk run berikutnya
return [{ json: { summaryText, hasAnomaly: anomalyFiles.length > 0 } }];

const rows = $json.values || [];
const trimmed = [];
const missingBarcodes = [];

for (const row of rows) {
  const nama = row[3]; // kolom D
  if (nama === undefined || nama === null || String(nama).trim() === '' || String(nama).trim().toUpperCase() === '#N/A') {
    break;
  }

  const barcode = row[2]; // kolom C (Barcode)
  if (String(barcode).trim().toUpperCase() === '#N/A') {
    missingBarcodes.push({ gin: row[0], pc: row[1], nama: row[3] });
  }

  trimmed.push(row);
}

const hasMissingBarcode = missingBarcodes.length > 0;
let htmlTable = '';
if (hasMissingBarcode) {
  htmlTable = `
    <p>Ditemukan <b>${missingBarcodes.length}</b> baris dengan Barcode tidak terdaftar di Master (Transaksi Summary):</p>
    <table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse; font-family:Arial, sans-serif; font-size:13px;">
      <tr style="background-color:#f2f2f2;"><th>GIN</th><th>PC</th><th>Nama Barang</th></tr>
      ${missingBarcodes.map(m => `<tr><td>${m.gin}</td><td>${m.pc}</td><td>${m.nama}</td></tr>`).join('')}
    </table>
    <p>Mohon lengkapi Barcode untuk barang-barang di atas di Master.</p>
  `;
}

return [{ json: { rows: trimmed, hasMissingBarcode, htmlTable } }];

const rows = $json.rows;

function toNumberIfPossible(v) {
  if (v === undefined || v === null || v === '') return v;
  const n = Number(String(v).replace(/[^0-9.\-]/g, ''));
  return (!isNaN(n) && String(v).trim() !== '') ? n : v;
}

const NUMERIC_COLS = [1, 2, 4, 5, 6, 7, 8]; // B, C, E, F, G, H, I (A=GIN dan D=nama dilewati, tetap teks)

const fixed = rows.map(row => {
  const r = [...row];
  for (const col of NUMERIC_COLS) {
    if (col < r.length) {
      r[col] = toNumberIfPossible(r[col]);
    }
  }
  return r;
});

return [{ json: { values: fixed } }];

const values = $json.values || [];

function isEmpty(v) {
  return v === null || v === undefined || v === '';
}

function toNumberIfPossible(v) {
  if (isEmpty(v)) return v;
  const n = Number(String(v).replace(/[^0-9.\-]/g, ''));
  return (!isNaN(n) && String(v).trim() !== '') ? n : v;
}

const NUMERIC_COLS = [0, 2, 6, 7]; // A, C, G, H

const fixed = values.map((row, i) => {
  if (i < 2) return row; // baris 1 (tanggal) & baris 2 (header) tidak diutak-atik
  const r = [...row];
  for (const col of NUMERIC_COLS) {
    if (col < r.length) {
      r[col] = toNumberIfPossible(r[col]);
    }
  }
  return r;
});

return [{ json: { values: fixed } }];

const values = $json.values || [];

const filtered = values.filter((row, i) => {
  if (i < 2) return true; // baris tanggal & header selalu ikut
  const h = Number(row[7]);
  return h !== 0 || isNaN(h);
});

// pisahkan 2 baris atas (tanggal + header) dari data supaya tidak ikut ke-sort
const headerRows = filtered.slice(0, 2);
const dataRows = filtered.slice(2);

// urutkan berdasarkan Description (kolom B, index 1), A-Z
dataRows.sort((a, b) => String(a[1] || '').localeCompare(String(b[1] || '')));

return [{ json: { values: [...headerRows, ...dataRows] } }];

const values = $json.values || [];
const dateRow = values[0] || [];   // baris "Transaksi tanggal : ..."
const header = values[1] || [];    // baris judul kolom (Barcode, Description, dst.)

const groups = {};
for (let i = 2; i < values.length; i++) {
  const row = values[i];
  if (!row || row.length === 0) continue;
  const personel = row[8]; // kolom I
  if (personel === undefined || personel === null || personel === '') continue;
  const key = String(personel).trim();
  if (!groups[key]) groups[key] = [];
  groups[key].push(row.slice(0, 8));
}

const items = Object.keys(groups).map(name => ({
  json: { sheetName: name, values: [dateRow.slice(0, 8), header, ...groups[name]] }
}));

return items;

const values = $json.values || [];
const missing = [];

for (let i = 2; i < values.length; i++) { // skip baris tanggal & header
  const row = values[i];
  if (!row || row.length === 0) continue;

  const barcode = row[0];
  if (barcode === undefined || barcode === null || String(barcode).trim() === '') continue; // lewati baris kosong (cuma formula, tidak ada data asli)

  const personel = row[8]; // kolom I
  if (String(personel).trim() === 'Tidak Ada') {
    missing.push({ barcode, description: row[1] });
  }
}

let summaryText = '';
if (missing.length > 0) {
  summaryText = 'Ditemukan ' + missing.length + ' barcode masuk kategori "Tidak Ada" (Personel tidak ketemu):\n\n';
  for (const m of missing) {
    summaryText += '- ' + m.barcode + ' (' + (m.description || 'nama tidak diketahui') + ')\n';
  }
}

return [{ json: { missing, hasMissing: missing.length > 0, summaryText } }];

const items = $('Group By Personel').all();
const output = [];

for (const item of items) {
  const sheetName = item.json.sheetName;
  if (sheetName === 'Tidak Ada') continue; // sheet ini tidak ada di template Telian

  const dataRows = item.json.values.slice(2); // lewati baris tanggal & header
  const telianRows = dataRows.map(row => row.slice(0, 8)); // copy utuh kolom A-H

  output.push({ json: { sheetName, values: telianRows } });
}

return output;

function toNumberIfPossible(v) {
  if (v === undefined || v === null || v === '') return v;
  const n = Number(String(v).replace(/[^0-9.\-]/g, ''));
  return (!isNaN(n) && String(v).trim() !== '') ? n : v;
}

const items = $input.all();
return items.map(item => {
  const rows = item.json.values.map(row => {
    const r = [...row];
    r[0] = toNumberIfPossible(r[0]); // Barcode
    r[7] = toNumberIfPossible(r[7]); // Jumlah (H)
    return r;
  });
  return { json: { sheetName: item.json.sheetName, values: rows } };
});

const rows = $json.values || [];
const trimmed = [];

for (const row of rows) {
  const gin = row[0];
  if (gin === undefined || gin === null || String(gin).trim() === '') break;
  trimmed.push(row.slice(0, 11));
}

const filtered = trimmed.filter(row => Number(row[8]) !== 0);

function alamatToKey(v) {
  const s = String(v).trim();
  if (s === '' || s.toUpperCase().includes('N/A')) return [Infinity]; // taruh di paling akhir
  return s.split('.').map(n => {
    const num = Number(n);
    return isNaN(num) ? Infinity : num;
  });
}

function compareAlamat(a, b) {
  const pa = alamatToKey(a);
  const pb = alamatToKey(b);
  const len = Math.max(pa.length, pb.length);
  for (let i = 0; i < len; i++) {
    const va = pa[i] ?? 0;
    const vb = pb[i] ?? 0;
    if (va !== vb) return va - vb;
  }
  return 0;
}

filtered.sort((a, b) => compareAlamat(a[9], b[9]));

return [{ json: { values: filtered } }];

