const calcRows = $('Read Pengambilan Calc For Penerimaan').first().json.values || [];
const lastRowData = $json.values || [];
const nextRow = lastRowData.length + 1;

function toNumberIfPossible(v) {
  if (v === undefined || v === null || v === '') return v;
  const n = Number(String(v).replace(/[^0-9.\-]/g, ''));
  return (!isNaN(n) && String(v).trim() !== '') ? n : v;
}

const trimmed = [];
for (const row of calcRows) {
  const barcode = row[0];
  if (barcode === undefined || barcode === null || String(barcode).trim() === '') break;
  trimmed.push(row.slice(0, 8));
}

const NUMERIC_COLS = [0, 2, 6, 7];
const fixedRows = trimmed.map(row => {
  const r = [...row];
  for (const col of NUMERIC_COLS) r[col] = toNumberIfPossible(r[col]);
  return r;
});

const attachmentName = $('Gmail Trigger').first().binary.attachment_0.fileName.replace('.zip', '');

const finalRows = fixedRows.map((row, i) => {
  const isFirst = i === 0;
  return [...row, '', '', isFirst ? attachmentName : ''];
});

return [{ json: { values: finalRows, nextRow } }];

const rekapRows = $('Read Cutoff Rekap Harian').first().json.values || [];
const lastRowData = $json.values || []; // dari Find Last Row Penjualan
const nextRow = lastRowData.length + 1;

function toNumberIfPossible(v) {
  if (v === undefined || v === null || v === '') return v;
  const n = Number(String(v).replace(/[^0-9.\-]/g, ''));
  return (!isNaN(n) && String(v).trim() !== '') ? n : v;
}

// ambil A:J saja (10 kolom), stop di baris pertama yang GIN-nya kosong
const trimmed = [];
for (const row of rekapRows) {
  const gin = row[0];
  if (gin === undefined || gin === null || String(gin).trim() === '') break;
  trimmed.push(row.slice(0, 10)); // A sampai J
}

// paksa kolom angka (B,C,E,F,G,H,I) jadi number murni -- tidak ada tanda petik
const NUMERIC_COLS = [1, 2, 4, 5, 6, 7, 8];
const fixedRows = trimmed.map(row => {
  const r = [...row];
  for (const col of NUMERIC_COLS) r[col] = toNumberIfPossible(r[col]);
  return r;
});

const attachmentName = $('Gmail Trigger').first().binary.attachment_0.fileName.replace('.zip', '');

// tanggal di kolom K, cuma diisi di BARIS PERTAMA
const finalRows = fixedRows.map((row, i) => {
  const isFirst = i === 0;
  return [...row, isFirst ? attachmentName : ''];
});

return [{ json: { values: finalRows, nextRow } }];

const rows = $json.values || []; // dari Trim Rekap Harian Data, kolom A-K (index 0-10)
const naItems = [];

for (const row of rows) {
  const alamat = row[9]; // kolom J
  if (String(alamat).trim() === '#N/A') {
    naItems.push({
      gin: row[0],
      pc: row[1],
      barcode: row[2],
      nama: row[3],
    });
  }
}

const attachmentName = $('Gmail Trigger').first().binary.attachment_0.fileName.replace('.zip', '');

let htmlTable = '';
if (naItems.length > 0) {
  htmlTable = `
    <p>Ditemukan <b>${naItems.length}</b> barang dengan Alamat tidak ketemu (#N/A) di file Penyiapan ${attachmentName}:</p>
    <table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse; font-family:Arial, sans-serif; font-size:13px;">
      <tr style="background-color:#f2f2f2;">
        <th>GIN</th><th>PC</th><th>Barcode</th><th>Nama Barang</th>
      </tr>
      ${naItems.map(item => `
      <tr>
        <td>${item.gin}</td>
        <td>${item.pc}</td>
        <td>${item.barcode}</td>
        <td>${item.nama}</td>
      </tr>`).join('')}
    </table>
    <p>Mohon lengkapi data Master untuk barang-barang di atas.</p>
  `;
}

return [{ json: { naItems, hasNA: naItems.length > 0, htmlTable, attachmentName } }];

function toNumberIfPossible(v) {
  if (v === undefined || v === null || v === '') return v;
  const n = Number(String(v).replace(/[^0-9.\-]/g, ''));
  return (!isNaN(n) && String(v).trim() !== '') ? n : v;
}

const rows = $json.values || [];
const trimmed = [];

for (const row of rows) {
  const gin = row[0]; // kolom A
  if (gin === undefined || gin === null || String(gin).trim() === '') break;
  trimmed.push(row.slice(0, 11)); // A sampai K = 11 kolom
}

// urutkan berdasarkan kolom A (Gin), kecil ke besar
trimmed.sort((a, b) => String(a[0]).localeCompare(String(b[0]), undefined, { numeric: true }));

// paksa kolom angka (B,C,E,F,G,H,I) jadi number murni -- A/D/J/K tetap teks
const NUMERIC_COLS = [1, 2, 4, 5, 6, 7, 8];
const fixed = trimmed.map(row => {
  const r = [...row];
  for (const col of NUMERIC_COLS) r[col] = toNumberIfPossible(r[col]);
  return r;
});

return [{ json: { values: fixed } }];

const processedRows = $json.values || [];
const actual = $('Gmail Trigger').first().binary.attachment_0.fileName.replace('.zip', '');

const alreadyProcessed = processedRows.some(row => row[0] === actual);

return [{ json: { isValid: !alreadyProcessed, attachmentName: actual } }];

