const staticData = $getWorkflowStaticData('global');
const duplicateFiles = staticData.duplicateFiles || [];
const newFileCount = staticData.newFileTabCounter || 0;
const newGins = staticData.newGins || [];

return [{ json: {
  hasNewFiles: newFileCount > 0,
  hasDuplicates: duplicateFiles.length > 0,
  duplicateFiles,
  newGins,
} }];

// Locks!B1 = waktu mulai Warehouse Pagi terakhir (ditulis Set Lock Running)
const GUARD_MS = 15 * 60 * 1000; // satu run butuh sekitar 4 menit
const row = ($json.values && $json.values[0]) || [];
const startedAt = row[1];

if (startedAt) {
  const age = Date.now() - new Date(startedAt).getTime();
  if (age < GUARD_MS) return []; // run lain baru mulai -- stop, jadwal berikutnya cek lagi
}

return [{ json: $('Validate Email Attachment').first().json }];
